      PregFaqPart(PregFaqSection.perspective, '', [
        'You do not have to give up feeling like yourself in pregnancy; a few small tweaks let you keep your routine with confidence.',
      ], []),
      PregFaqPart(PregFaqSection.takeaways, '', [], [
